declare(strict_types=1);require_once dirname(__DIR__,2).'/config.php';require_once ROOT_PATH.'/database/config/db.php';require_once ROOT_PATH.'/security/middleware/AuthMiddleware.php';require_once ROOT_PATH.'/services/OnlyOfficeService.php';require_once ROOT_PATH.'/services/CoworkspaceService.php';
AuthMiddleware::startSession();$user=AuthMiddleware::requireAuth(true);header('Content-Type: application/json; charset=utf-8');$db=Database::getInstance();$uid=(int)$user['id'];
function jsonFail(string $message,int $status=400):never{http_response_code($status);echo json_encode(['success'=>false,'error'=>$message]);exit;}function input():array{$v=json_decode(file_get_contents('php://input'),true);return is_array($v)?$v:$_POST;}
function resolveWorkspace(PDO $db,int $uid,array $in):array{$wid=(int)($in['workspace_id']??$_GET['workspace_id']??0);if($wid>0)return CoworkspaceService::get($db,$wid,$uid);$cid=(int)($in['channel_id']??$_GET['channel_id']??0);if($cid<1)throw new RuntimeException('A Coworkspace is required.',400);$s=$db->prepare('SELECT c.server_id FROM channels c INNER JOIN server_members sm ON sm.server_id=c.server_id AND sm.user_id=:uid AND sm.status="active" WHERE c.id=:cid LIMIT 1');$s->execute([':uid'=>$uid,':cid'=>$cid]);$sid=(int)$s->fetchColumn();if($sid<1)throw new RuntimeException('You are not a member of this server.',403);$s=$db->prepare('SELECT id FROM collab_workspaces WHERE server_id=:sid AND archived=0 ORDER BY id ASC LIMIT 1');$s->execute([':sid'=>$sid]);$wid=(int)$s->fetchColumn();if($wid<1)throw new RuntimeException('The server Coworkspace has not been synchronized yet.',404);return CoworkspaceService::get($db,$wid,$uid);}
function docAccess(PDO $db,array $w,int $uid,int $id):array{$s=$db->prepare('SELECT id,created_by,visibility,public_permission FROM collab_documents WHERE id=:id AND workspace_id=:wid LIMIT 1');$s->execute([':id'=>$id,':wid'=>(int)$w['id']]);$d=$s->fetch(PDO::FETCH_ASSOC);if(!$d)jsonFail('Document not found.',404);$owner=(int)$d['created_by']===$uid||(int)$w['host_id']===$uid;$s=$db->prepare('SELECT permission FROM collab_resource_permissions WHERE resource_type="document" AND resource_id=:rid AND user_id=:uid LIMIT 1');$s->execute([':rid'=>$id,':uid'=>$uid]);$p=$s->fetchColumn();if(!$owner&&$d['visibility']==='private'&&$p===false)jsonFail('This private document has not been shared with you.',403);return [$d,$owner,$p===false?null:(string)$p];}
function writeZip(ZipArchive $z,string $p,string $c):void{$z->addFromString($p,$c);}function createOoxmlTemplate(string $type,string $path):bool{$z=new ZipArchive();if($z->open($path,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true)return false;if($type==='docx'){writeZip($z,'[Content_Types].xml','<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>');writeZip($z,'_rels/.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>');writeZip($z,'word/document.xml','<?xml version="1.0"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body><w:p><w:r><w:t>Start collaborating in eCollab.</w:t></w:r></w:p><w:sectPr/></w:body></w:document>');writeZip($z,'word/_rels/document.xml.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"/>');}elseif($type==='xlsx'){writeZip($z,'[Content_Types].xml','<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>');writeZip($z,'_rels/.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');writeZip($z,'xl/workbook.xml','<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Sheet1" sheetId="1" r:id="rId1"/></sheets></workbook>');writeZip($z,'xl/_rels/workbook.xml.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"/>');writeZip($z,'xl/worksheets/sheet1.xml','<?xml version="1.0"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData><row r="1"><c r="A1" t="inlineStr"><is><t>Start collaborating in eCollab.</t></is></c></row></sheetData></worksheet>');}else{writeZip($z,'[Content_Types].xml','<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/ppt/presentation.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.presentation.main+xml"/></Types>');writeZip($z,'_rels/.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="ppt/presentation.xml"/></Relationships>');writeZip($z,'ppt/presentation.xml','<?xml version="1.0"?><p:presentation xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main"><p:sldMasterIdLst/><p:sldIdLst/><p:sldSz cx="12192000" cy="6858000" type="screen16x9"/></p:presentation>');writeZip($z,'ppt/_rels/presentation.xml.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"/>');}return $z->close();}
try{$method=strtoupper($_SERVER['REQUEST_METHOD']??'GET');$data=$method==='GET'?$_GET:input();$w=resolveWorkspace($db,$uid,$data);$wid=(int)$w['id'];if($method==='GET'){$vf=strtolower(trim((string)($_GET['visibility']??'all')));$where='workspace_id=:wid';$params=[':wid'=>$wid];if(in_array($vf,['public','private'],true)){$where.=' AND visibility=:visibility';$params[':visibility']=$vf;}$s=$db->prepare('SELECT id,title,file_name,file_type,document_key,version,created_by,updated_by,visibility,public_permission,created_at,updated_at FROM collab_documents WHERE '.$where.' ORDER BY updated_at DESC,id DESC');$s->execute($params);$docs=[];$presence=[];foreach($s->fetchAll(PDO::FETCH_ASSOC) as $d){[$x,$owner,$perm]=docAccess($db,$w,$uid,(int)$d['id']);$d['can_edit']=$owner||$perm==='edit'||($d['visibility']==='public'&&($d['public_permission']??'view')==='edit');$d['can_manage']=$owner;$d['access_permission']=$owner?'edit':($perm?:($d['visibility']==='public'?($d['public_permission']??'view'):null));$d['open_url']=BASE_URL.'/modules/collaboration/document.php?id='.(int)$d['id'].'&workspace_id='.$wid;$d['file_url']=OnlyOfficeService::signedFileUrl((int)$d['id'],(string)$d['document_key']);unset($d['document_key']);$docs[]=$d;}$ids=array_map(fn($d)=>(int)$d['id'],$docs);if($ids){$q=implode(',',array_fill(0,count($ids),'?'));$p=$db->prepare('SELECT p.document_id,p.user_id,p.mode,p.last_seen,COALESCE(NULLIF(u.full_name,""),u.username) display_name FROM collab_document_presence p INNER JOIN users u ON u.id=p.user_id WHERE p.document_id IN ('.$q.') AND p.last_seen >= (NOW()-INTERVAL 45 SECOND) ORDER BY p.document_id,p.mode,display_name');$p->execute($ids);foreach($p->fetchAll(PDO::FETCH_ASSOC) as $r)$presence[(int)$r['document_id']][]=['user_id'=>(int)$r['user_id'],'mode'=>$r['mode'],'display_name'=>$r['display_name'],'last_seen'=>$r['last_seen']];}foreach($docs as &$d){$u=$presence[(int)$d['id']]??[];$ed=count(array_filter($u,fn($p)=>$p['mode']==='editing'));$d['presence']=['total'=>count($u),'editing'=>$ed,'viewing'=>count($u)-$ed,'users'=>$u];}unset($d);echo json_encode(['success'=>true,'workspace'=>$wid,'documents'=>$docs]);exit;}if($method!=='POST')jsonFail('Method not allowed.',405);AuthMiddleware::verifyCsrf();$title=trim((string)($data['title']??'Untitled Document'));$type=strtolower(trim((string)($data['type']??'docx')));$visibility=strtolower(trim((string)($data['visibility']??'public')));$title=trim(substr(preg_replace('~[\\\\/:*?"<>|]+~',' ',$title)?:'Untitled Document',0,220));if($title==='')$title='Untitled Document';if(!in_array($type,['docx','xlsx','pptx'],true))jsonFail('Supported formats are DOCX, XLSX and PPTX.');if(!in_array($visibility,['public','private'],true))jsonFail('Visibility must be public or private.');$role=(string)($w['member_role']??'');if((int)$w['allow_create_documents']!==1&&!in_array($role,['host','editor'],true))jsonFail('Document creation is disabled for this Coworkspace.',403);$dir=ROOT_PATH.'/uploads/collab-docs';if(!is_dir($dir)&&!mkdir($dir,0750,true)&&!is_dir($dir))jsonFail('Document storage is unavailable.',500);$key=bin2hex(random_bytes(24));$ext='.'.$type;$fileName=$title.$ext;$storageName=$key.$ext;$path=$dir.DIRECTORY_SEPARATOR.$storageName;if(!class_exists('ZipArchive')||!createOoxmlTemplate($type,$path)){@unlink($path);jsonFail('Could not create the document.',500);}$s=$db->prepare('INSERT INTO collab_documents(channel_id,workspace_id,title,file_name,file_type,storage_path,document_key,visibility,public_permission,created_by,updated_by) VALUES(:cid,:wid,:title,:name,:type,:path,:key,:visibility,"view",:created_by,:updated_by)');$s->execute([':cid'=>(int)$w['channel_id'],':wid'=>$wid,':title'=>$title,':name'=>$fileName,':type'=>$type,':path'=>'uploads/collab-docs/'.$storageName,':key'=>$key,':visibility'=>$visibility,':created_by'=>$uid,':updated_by'=>$uid]);$id=(int)$db->lastInsertId();$db->prepare('INSERT INTO collab_resource_permissions(resource_type,resource_id,workspace_id,user_id,permission,granted_by) VALUES("document",:rid,:wid,:uid,"edit",:uid)')->execute([':rid'=>$id,':wid'=>$wid,':uid'=>$uid]);echo json_encode(['success'=>true,'document'=>['id'=>$id,'title'=>$title,'file_name'=>$fileName,'file_type'=>$type,'visibility'=>$visibility,'public_permission'=>'view','workspace_id'=>$wid,'open_url'=>BASE_URL.'/modules/collaboration/document.php?id='.$id.'&workspace_id='.$wid]]);}catch(Throwable $e){$status=(int)$e->getCode();jsonFail($e->getMessage(),($status>=400&&$status<600)?$status:500);}
